// Qualitative CBF vs PaO2: CBF(P) = 1 for P >= 8.5 kPa, else 1 + 0.08*(8.5 - P)^2.
const X0 = 100, X1 = 580, YB = 468, YT = 150;            // plot box: PaO2 0..16 kPa, CBF 0.8..3.1
const VB = 0.8, VT = 3.1, KNEE = 8.5, P0 = 13, PT = 6.7;
const sx = p => X0 + (X1 - X0) * p / 16;
const sy = v => YB - (YB - YT) * (v - VB) / (VT - VB);
const cbf = p => p >= KNEE ? 1 : 1 + 0.08 * (KNEE - p) * (KNEE - p);
const TEAL = "#2a9d8f", RED = "#c0392b";
const YN = sy(1), YP = sy(cbf(PT));                       // normal level, patient's point on the curve
const CX = 488, CY = 232;                                 // arteriole inset centre (inset x 396..580)
const INSET_BOTTOM = 346;
const CHIP_H = 32, PAD = 14;
const AX = sx(PT) + 32;                                   // up-arrow beside the patient point
const AOFF = 14;                                          // arrow sits just above the curve, same length as the rise
let el = {};
function txt(api, parent, s, attrs) {
  const t = api.el("text", Object.assign({"font-family": "system-ui,sans-serif", "font-weight": 700}, attrs), parent);
  t.textContent = s; return t;
}
function setup(api) {
  const grid = api.$("#grid"), ticks = api.$("#ticks"), plot = api.$("#plot"), inset = api.$("#inset");
  for (let p = 0; p <= 16; p += 4) {
    // Gridlines under the inset stop short of it instead of running beneath the box.
    if (p > 0) api.el("line", {x1: sx(p), y1: YB, x2: sx(p), y2: sx(p) >= 396 ? INSET_BOTTOM + 16 : YT}, grid);
    api.el("line", {x1: sx(p), y1: YB, x2: sx(p), y2: YB + 7, stroke: "@ink", "stroke-width": 2.5}, ticks);
    txt(api, ticks, String(p), {x: sx(p), y: YB + 29, "text-anchor": "middle", "font-weight": 600});
  }
  // Normal reference level.
  api.el("line", {x1: X0, y1: YN, x2: X1, y2: YN, stroke: "@muted", "stroke-width": 2, "stroke-dasharray": "7 7", opacity: 0.85}, plot);
  txt(api, plot, "normal", {x: X1, y: YN - 14, "text-anchor": "end", fill: "@muted", "font-size": 18});
  // Rising limb (8.5 -> 3.5 kPa), computed from the formula, solid red, drawn on in beat 3.
  let d = "";
  el.lp = []; el.cum = [0];
  let px = 0, py = 0;
  for (let i = 0; i <= 100; i++) {
    const p = KNEE - 5 * i / 100, x = sx(p), y = sy(cbf(p));
    d += (i ? " L " : "M ") + x.toFixed(2) + " " + y.toFixed(2);
    el.lp.push(p);
    if (i) el.cum.push(el.cum[i - 1] + Math.hypot(x - px, y - py));
    px = x; py = y;
  }
  el.total = el.cum[100];
  el.limb = api.el("path", {d: d, fill: "none", stroke: RED, "stroke-width": 6, "stroke-linecap": "round", "stroke-linejoin": "round", pathLength: 1}, plot);
  // Flat limb (16 -> 8.5 kPa) on top, so its round teal cap closes the join at the knee.
  api.el("path", {d: "M " + sx(16) + " " + YN + " L " + sx(KNEE) + " " + YN, fill: "none", stroke: TEAL, "stroke-width": 6, "stroke-linecap": "round"}, plot);
  // Patient marker, dashed guide to the axis, PaO2 chip.
  el.guide = api.el("line", {stroke: "@muted", "stroke-width": 2, "stroke-dasharray": "4 5"}, plot);
  el.chip = api.el("g", {}, plot);
  // The chip reads "PaO₂" while the marker slides and widens to "PaO₂ 6.7 kPa" as it arrives (never mislabels the marker).
  el.chipBox = api.el("rect", {x: 0, y: 0, height: CHIP_H, rx: 16, fill: "#fdeeec", stroke: "#efb3aa", "stroke-width": 1.5, filter: "url(#chipShadow)"}, el.chip);
  const clip = api.el("clipPath", {id: "chipClip"}, el.chip);
  el.chipClip = api.el("rect", {x: 3, y: 0, height: CHIP_H}, clip);
  const label = api.el("text", {x: PAD, y: CHIP_H / 2 + 1, "dominant-baseline": "central", "clip-path": "url(#chipClip)", fill: "#b03024", "font-size": 17, "font-weight": 700, "font-family": "system-ui,sans-serif"}, el.chip);
  const t1 = api.el("tspan", {}, label); t1.textContent = "PaO₂ ";
  el.value = api.el("tspan", {}, label); el.value.textContent = "6.7 kPa";
  const w1 = t1.getComputedTextLength() || 46, wf = label.getComputedTextLength() || 104;
  el.wSmall = PAD + w1 + PAD - 4; el.wFull = PAD + wf + PAD;
  // Beat 3: red up-arrow beside the patient point; its length equals the computed rise (normal -> patient CBF).
  el.upLine = api.el("line", {stroke: RED, "stroke-width": 6, "stroke-linecap": "round"}, plot);
  el.upHead = api.el("path", {fill: RED, stroke: RED, "stroke-width": 2, "stroke-linejoin": "round"}, plot);
  el.cbfLabel = txt(api, plot, "CBF ↑", {x: AX + 14, y: YP - 4, fill: RED, "font-size": 20, stroke: "#ffffff", "stroke-width": 5, "stroke-linejoin": "round", "paint-order": "stroke"});
  el.haloN = api.el("circle", {r: 17, fill: TEAL}, plot);
  el.haloH = api.el("circle", {r: 17, fill: RED}, plot);
  el.dot = api.el("circle", {r: 9, fill: TEAL, stroke: "#ffffff", "stroke-width": 3}, plot);
  el.core = api.el("circle", {fill: RED}, plot);
  // Arteriole cross-section: muscular wall, endothelium, red lumen, smooth-muscle nuclei.
  el.wall = api.el("circle", {cx: CX, cy: CY, fill: "url(#wallFill)", stroke: "#c9786c", "stroke-width": 2}, inset);
  el.nuclei = [];
  for (let i = 0; i < 14; i++) el.nuclei.push(api.el("ellipse", {fill: "#a8453c", "fill-opacity": 0.55}, inset));
  el.endo = api.el("circle", {cx: CX, cy: CY, fill: "#fbe7e2", stroke: "#e9b9b0", "stroke-width": 1}, inset);
  el.lumen = api.el("circle", {cx: CX, cy: CY, fill: "url(#lumenFill)"}, inset);
  el.shine = api.el("ellipse", {fill: "#ffffff", "fill-opacity": 0.22}, inset);
  el.push = [];
  for (let i = 0; i < 4; i++) {
    const g = api.el("g", {}, inset);
    api.el("line", {x1: 0, y1: 0, x2: 12, y2: 0, stroke: "@accent", "stroke-width": 4, "stroke-linecap": "round"}, g);
    api.el("path", {d: "M 10 -6 L 19 0 L 10 6 Z", fill: "@accent", stroke: "@accent", "stroke-width": 1.5, "stroke-linejoin": "round"}, g);
    el.push.push(g);
  }
  el.dilLabel = txt(api, inset, "arteriole dilates", {x: CX, y: 324, "text-anchor": "middle", fill: "@ink", "font-size": 18});
}
function fade(api, node, k) { api.set(node, {opacity: k, display: k > 0 ? "inline" : "none"}); }
// PaO2 at the drawing tip of the rising limb, from its arc-length fraction (exact for the polyline).
function tipP(dr) {
  if (dr <= 0) return KNEE;
  const target = dr * el.total;
  for (let i = 1; i <= 100; i++) {
    if (el.cum[i] >= target) {
      const f = (target - el.cum[i - 1]) / (el.cum[i] - el.cum[i - 1]);
      return el.lp[i - 1] + (el.lp[i] - el.lp[i - 1]) * f;
    }
  }
  return el.lp[100];
}
function render(t, api) {
  // Beat 1: PaO2 falls from 13 to 6.7 kPa; the marker slides along the normal level and turns red.
  const s = api.seg(t, 200, 2200, "ease_in_out");
  const mx = sx(P0 + (PT - P0) * s);
  // Beat 3: the rising limb draws on from 8.5 down to 3.5 kPa; the marker rides the drawing tip up onto the curve.
  const dr = api.seg(t, 5000, 6300, "sine");
  const my = sy(cbf(Math.max(PT, tipP(dr))));
  api.set(el.limb, {"stroke-dasharray": dr.toFixed(4) + " 1.001"});
  fade(api, el.limb, dr > 0 ? 1 : 0);
  const h = api.ease("ease_in_out", (s - 0.45) / 0.4);      // marker turns red as PaO2 falls (red core grows, no muddy blend)
  api.set(el.haloN, {cx: mx, cy: my, "fill-opacity": 0.2 * (1 - h)});
  api.set(el.haloH, {cx: mx, cy: my, "fill-opacity": 0.2 * h});
  api.set(el.dot, {cx: mx, cy: my});
  api.set(el.core, {cx: mx, cy: my, r: 7.5 * h});
  api.set(el.guide, {x1: mx, y1: my + 11, x2: mx, y2: YB - 2});
  const v = api.seg(t, 1700, 2200, "ease_in_out");
  const w = el.wSmall + (el.wFull - el.wSmall) * v;
  api.set(el.chipBox, {width: w}); api.set(el.chipClip, {width: w - 6});
  api.set(el.value, {"fill-opacity": api.seg(t, 1750, 2200)});
  api.set(el.chip, {transform: "translate(" + (mx - 18 - w).toFixed(1) + " " + (YN - 27 - CHIP_H / 2).toFixed(1) + ")"});
  // Beat 2: the arteriole dilates (lumen radius +35 %, wall thins).
  const k = api.seg(t, 2800, 4000, "ease_in_out");
  const rl = 26 + 9 * k, ro = 56 + 2 * k, re = rl + 3;
  api.set(el.wall, {r: ro}); api.set(el.endo, {r: re}); api.set(el.lumen, {r: rl});
  api.set(el.shine, {cx: CX - rl * 0.32, cy: CY - rl * 0.38, rx: rl * 0.42, ry: rl * 0.24, transform: "rotate(-30 " + (CX - rl * 0.32).toFixed(1) + " " + (CY - rl * 0.38).toFixed(1) + ")"});
  const rm = (re + ro) / 2;
  el.nuclei.forEach((n, i) => {
    const a = (i + 0.5) * 2 * Math.PI / el.nuclei.length, x = CX + rm * Math.cos(a), y = CY + rm * Math.sin(a);
    api.set(n, {cx: x, cy: y, rx: 6.5 + 1.8 * k, ry: 2.8 - 0.7 * k, transform: "rotate(" + (a * 180 / Math.PI + 90).toFixed(1) + " " + x.toFixed(1) + " " + y.toFixed(1) + ")"});
  });
  const pk = api.seg(t, 2800, 3300, "ease_out") * (1 - api.seg(t, 4400, 4900));
  el.push.forEach((g, i) => {
    const a = 45 + 90 * i, r = ro + 6 + 8 * k;
    api.set(g, {transform: "rotate(" + a + " " + CX + " " + CY + ") translate(" + (CX + r).toFixed(1) + " " + CY + ")"});
    fade(api, g, pk);
  });
  const lk = api.seg(t, 2900, 3400, "ease_out");
  fade(api, el.dilLabel, lk);
  api.set(el.dilLabel, {transform: "translate(0 " + ((1 - lk) * 8).toFixed(1) + ")"});
  // Beat 3: the up-arrow grows beside the patient point as the marker climbs; it spans the rise YN -> YP.
  const ak = api.seg(t, 5200, 5700, "ease_out");
  const ay0 = YN - AOFF, ay1 = ay0 - (YN - YP) * ak;      // base just above the curve, tip at the patient level (same offset)
  api.set(el.upLine, {x1: AX, y1: ay0, x2: AX, y2: Math.min(ay0, ay1 + 9)});
  api.set(el.upHead, {d: "M " + (AX - 9) + " " + (ay1 + 12).toFixed(1) + " L " + AX + " " + ay1.toFixed(1) + " L " + (AX + 9) + " " + (ay1 + 12).toFixed(1) + " Z"});
  fade(api, el.upLine, ak > 0 ? Math.min(1, ak * 3) : 0); fade(api, el.upHead, ak > 0 ? Math.min(1, ak * 3) : 0);
  const bk = api.seg(t, 5250, 5750, "ease_out");
  fade(api, el.cbfLabel, bk);
  api.set(el.cbfLabel, {transform: "translate(" + ((1 - bk) * -10).toFixed(1) + " 0)"});
}
